#!/usr/bin/env python3
"""Write site/example data from the Soil example sources."""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent


def items_for(directory):
    items = []
    for path in sorted((root / "examples" / directory).glob("*.soil")):
        if path.name == "prelude.soil":
            continue
        items.append((path.stem, path.read_text()))
    return items


def write_code(path, constant, items):
    lines = [
        "; SPDX-License-Identifier: MIT OR Apache-2.0",
        "; Generated by site/gen-examples.py. Do not edit.",
        f"(defconst {constant}",
        "  (list",
    ]
    for slug, code in items:
        lines.append(
            f"    (list (list :slug {json.dumps(slug)}) "
            f"(list :code {json.dumps(code, ensure_ascii=False)}))"
        )
    lines += ["  ))", ""]
    path.write_text("\n".join(lines))


write_code(root / "site" / "examples-code.soil", "example-code", items_for("ui"))
write_code(root / "site" / "lisp-code.soil", "lisp-code", items_for("lisp"))
